-- Development-only seed data for local D1.
-- Dates and values are generated by seed-data.ts so weekly comparisons stay current.
-- Rows belong to the user `POST /api/auth/dev-login` signs in as (identity dev/dev), created here when missing.

INSERT INTO users (id, display_name, email, created_at, updated_at)
SELECT 'dev-seed:user', 'Dev', NULL, {{timestamp}}, {{timestamp}}
WHERE NOT EXISTS (
  SELECT 1 FROM user_identities WHERE provider = 'dev' AND provider_user_id = 'dev'
);

INSERT INTO user_identities (provider, provider_user_id, user_id, email, created_at)
VALUES ('dev', 'dev', 'dev-seed:user', NULL, {{timestamp}})
ON CONFLICT(provider, provider_user_id) DO NOTHING;

INSERT INTO measurements (
  id,
  user_id,
  date,
  weight_kg,
  body_fat_percentage,
  muscle_percentage,
  resting_metabolism_kcal,
  created_at,
  updated_at
)
VALUES
{{rows}}
ON CONFLICT(user_id, date) DO UPDATE SET
  weight_kg = excluded.weight_kg,
  body_fat_percentage = excluded.body_fat_percentage,
  muscle_percentage = excluded.muscle_percentage,
  resting_metabolism_kcal = excluded.resting_metabolism_kcal,
  updated_at = excluded.updated_at
WHERE measurements.id LIKE 'dev-seed:%';
